<h1>People</h1><form method="get" action="/people" class="row"><input type="search" name="q" value="<?= htmlspecialchars( (string) ( $search ?? '' ), ENT_QUOTES, 'UTF-8' ) ?>" placeholder="Search people"><button>Search</button></form><div class="people"><?php foreach ( $people as $person ) : ?><article class="person"><strong><?= htmlspecialchars( $person['name'], ENT_QUOTES, 'UTF-8' ) ?></strong><small>Born <?= htmlspecialchars( $person['birth_date'], ENT_QUOTES, 'UTF-8' ) ?><?= null !== $person['death_date'] ? ' · Died ' . htmlspecialchars( $person['death_date'], ENT_QUOTES, 'UTF-8' ) : '' ?></small></article><?php endforeach; ?></div><?php if ( empty( $people ) ) : ?><p>No profiles match.</p><?php endif; ?>
